import * as THREE from 'three/webgpu';
import {
  texture,
  positionLocal,
  uv,
  mul,
  add,
  float,
  sampler2D,
  vec3
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures asynchronously via ctx
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthMapTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Set color space for proper rendering
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Create tessellated plane for detailed displacement
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  // Setup TSL-based displacement material
  const colorSampler = sampler2D(imageTexture);
  const depthSampler = sampler2D(depthMapTexture);

  // Calculate displacement from depth map
  const displacementStrength = float(0.08);
  const depthSample = texture(depthSampler, uv()).x;
  const displacementOffset = mul(depthSample, displacementStrength);

  // Displace vertices in Z direction
  const displacedPosition = add(
    positionLocal,
    mul(vec3(0, 0, 1), displacementOffset)
  );

  // Create NodeMaterial with TSL nodes
  const material = new THREE.NodeMaterial();
  material.positionNode = displacedPosition;
  material.colorNode = texture(colorSampler, uv());
  material.side = THREE.FrontSide;

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply position and scale from config
  if (config.sceneConfig) {
    const [px, py, pz] = config.sceneConfig.position || [0, 0, 0];
    const [sx, sy, sz] = config.sceneConfig.scale || [1, 1, 1];
    mesh.position.set(px, py, pz);
    mesh.scale.set(sx, sy, sz);
  }

  group.add(mesh);

  // Apply cinematic primitives as specified in config
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params || {});
      }
    });
  }

  // Track timelines for cleanup
  const timelines = [];
  const originalPos = mesh.position.clone();

  // Event handlers
  const handlers = {};

  // Hover enter: subtle rise-in effect (0.15 scene units)
  handlers.mouseenter = function() {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: originalPos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
    timelines.push(tl);
  };

  // Hover leave: return to original position
  handlers.mouseleave = function() {
    gsap.to(mesh.position, {
      y: originalPos.y,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click: signal hub-pricing.select event
  handlers.click = function() {
    group.userData.eventType = 'hub-pricing.select';
  };

  // Attach handlers to userData
  group.userData.handlers = handlers;
  group.userData.eventType = null;

  // Cleanup function disposes resources and kills timelines
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthMapTexture.dispose();
  };

  return group;
}
